ục vụ nếu dữ liệu hiện tại không xác nhận.\n\nKhi khách hỏi đường đi, hãy nêu địa chỉ và hướng đến trang Giới thiệu & Liên hệ để xem bản đồ. Nếu khách cần xác nhận dịch vụ đặc biệt, hãy hướng đến lễ tân; không hứa đã ghi nhận yêu cầu thay cho nhân viên.','ce2abd609e2cfc297e2b9022ae110aa34aeb57f4ea5e1df98f8b5ce28cd6ab9d','[-0.000063136256,0.018887307,-0.013800698,-0.036750868,-0.020603225,0.002096934,-0.014309565,0.02740202,-0.016639333,-0.04169812,-0.018992454,0.002910701,0.007838899,0.021777915,0.134937,0.000756055,0.025903624,-0.00040357438,-0.003566901,0.005234239,0.025917193,0.003469695,-0.016702276,-0.02390787,0.019760385,0.012413743,-0.0137279695,0.031937122,0.019111939,-0.0018625995,-0.005065856,0.0035077948,-0.014186743,0.030333009,0.00097067404,0.0103482315,0.007418315,-0.0014130679,-0.005752386,0.023306943,-0.0026582733,0.0024691392,-0.01930926,-0.010330453,-0.030929212,-0.026766535,-0.003496523,-0.04380061,0.0008504601,0.023210384,0.012096993,0.020327784,-0.025937688,-0.18049163,-0.0052602384,-0.013855899,0.015083273,0.013616435,-0.017013714,-0.019044874,0.011842681,0.0076682633,-0.021744639,-0.0019101254,-0.008864793,0.0057226885,0.024504427,-0.0048460807,-0.0068671973,-0.020249588,0.011056282,0.00737883,0.01006282,-0.020576496,0.0075660273,-0.017974565,-0.005155879,-0.0037309558,-0.0015910111,-0.01219649,-0.01929872,-0.020638576,-0.010398482,-0.023858977,0.029257787,-0.0070161466,0.021635976,0.017958416,-0.0024432146,0.022007287,0.035898816,0.016053414,0.014598134,0.0015842483,0.028669702,-0.0028103534,-0.020296399,-0.025270104,-0.020924926,0.018439764,0.00024383796,0.009946755,-0.011133265,0.0010778347,0.015299701,-0.020703053,0.018681543,-0.0046882993,-0.01916206,0.008541091,0.012275622,-0.0015323071,0.008910933,-0.010129635,-0.0142961135,-0.16060227,0.026383655,-0.0017355854,-0.0058309357,-0.023249028,-0.01585603,-0.004529012,0.0056193275,0.043071773,-0.008698215,-0.017207306,0.01859812,0.008658961,-0.0314636,-0.014380322,-0.020685557,0.008726799,0.0