ực tiếp khác tài liệu này, ưu tiên dữ liệu trực tiếp.\n\nKhông suy ra số phòng còn trống, giá hiện tại, diện tích, loại giường, hướng nhìn hay tiện nghi từ tên hạng phòng. Khách có thể xem tiện nghi trong chi tiết hạng phòng. Khi gợi ý phòng, so sánh riêng số người lớn, trẻ em và tổng số khách với sức chứa, đồng thời kiểm tra số phòng khách muốn đặt.','4e8b93aa1d3669630b176c9b5412886afd00e7a004fef39b4c06b937d46598bb','[-0.025505329,-0.0021060775,-0.011063812,-0.03199104,-0.0074875895,-0.0013150757,-0.016641555,-0.0043003988,-0.0032464885,-0.011288105,-0.01452053,0.019894062,0.0040974785,-0.014973869,0.12568527,0.00817581,0.017780496,0.029488472,0.0025105753,0.021750724,-0.010120712,-0.0051790304,0.019915054,-0.0027196123,-0.013496774,-0.0049276496,-0.021708844,-0.006469944,0.018722279,0.00953122,-0.009820867,0.0141264675,-0.008012495,0.004418062,-0.026041895,0.02392041,-0.00634994,-0.014211406,0.0031089738,0.02343004,-0.015559135,0.039609227,-0.009288902,-0.016685387,-0.006074182,0.006968618,-0.011759244,-0.013842258,0.0020128922,0.02658326,0.01169287,-0.0035116419,-0.03188681,-0.17223586,0.016579619,-0.018342339,-0.0032339303,-0.0039569293,-0.016068775,-0.0025397544,-0.01194853,0.016335871,-0.020064985,-0.010001285,-0.009627551,0.018973859,0.026397066,0.020128712,0.004846563,-0.010788596,0.024869421,-0.00856332,-0.031596236,-0.030620484,-0.022677792,-0.015184528,-0.00085189426,-0.013110701,-0.0031022488,-0.0020494135,0.0241998,-0.011152129,-0.031481188,-0.024096414,0.008547635,-0.017023237,0.008587809,-0.019565137,-0.025190277,0.009241371,0.024272554,0.00695453,0.024934785,-0.027725093,0.009682797,0.007955475,0.025596032,0.013253196,-0.03831542,0.022874143,0.0019578745,0.014390479,-0.011086564,-0.015377916,-0.00087150035,-0.0044877143,0.003380531,-0.010596546,-0.02501392,0.008982526,0.019810926,-0.016331486,0.007373197,-0.0005475621,0.00038962066,-0.14229587,-0.013149896,-0.0071050436,-0.015769694,0.0035977308,-0.0040899473,0.011395208,0.007405426,0.013228876,-0.01