 phòng.\n\nĐơn chờ thanh toán giữ phòng tối đa 10 phút. Nếu thời gian này hết mà chưa hoàn tất thanh toán, hệ thống có thể hủy đơn và trả phòng về danh sách khả dụng. Pico chỉ đọc dữ liệu và hướng dẫn khách; Pico không tạo, giữ, sửa hay xác nhận đặt phòng thay khách.','ed6d09a2a94a1abc384b31d66c07d6151ac0fcd5b3ada13b6df05a2990a13c37','[0.015925828,0.007434271,-0.020276526,-0.05614677,-0.010775206,-0.0019158154,-0.032952327,-0.0012499511,-0.021185746,-0.025130363,-0.001624055,0.0026243022,0.0036060722,-0.012450561,0.119854495,0.009210945,0.0044897413,0.0045691365,-0.0129993595,0.014017873,0.001742648,0.024958296,-0.01779639,0.0122421635,0.038948484,0.008144774,0.016261052,0.038809728,0.04642642,0.0061248736,-0.009499997,0.0011121441,-0.016939763,0.020373078,0.016180942,0.013625065,0.009584013,-0.00044489925,-0.018084997,0.030731555,-0.010588764,0.007619079,-0.024087783,-0.004977613,0.00061313796,-0.009534255,-0.0069161593,-0.018522914,0.0022599313,0.0143108955,0.02096723,0.020341538,-0.00095754466,-0.19129115,0.010872528,-0.014292731,0.008760379,0.018356463,-0.013890296,-0.03535244,-0.011397294,0.020683508,0.01163313,0.0135740135,0.006889909,0.040720623,0.022844156,0.010053344,-0.0003663226,-0.020174598,0.01901148,0.003531034,0.015079441,-0.002198327,-0.0074136807,-0.020687692,0.014695794,0.0384086,-0.004104295,0.004300513,-0.000050607105,-0.016518071,-0.0073191333,-0.028661512,0.027225493,-0.015081986,0.025630165,0.013690264,-0.012867723,-0.0061288797,0.009661471,-0.002521063,0.019929294,-0.01695805,-0.006905408,0.004589025,-0.010217986,-0.0023261097,-0.02988187,-0.00896153,-0.014132196,-0.01611438,-0.012547378,0.011119928,0.017942926,-0.017749859,0.017322246,0.009861795,-0.00431489,-0.0026908347,0.020937145,-0.02148286,0.021039212,0.0059119817,-0.008999724,-0.13699202,-0.008184309,-0.016462639,-0.018318392,-0.00057470886,0.00013899009,-0.023128022,-0.0029467861,0.008655204,-0.019737305,-0.0390659,0.0059766686,0.017056026,-0.032999028,-0.014045562,-0.009690164,0.010