chưa đăng nhập, Pico hướng dẫn đăng nhập; Pico không yêu cầu khách gửi số thẻ, mật khẩu, OTP hoặc mã thanh toán qua chat. Không đọc hay tiết lộ đơn của người khác.','00038ee4247bd96e14706fd7ba3a9a51aceb82d1db0d0aa1cb154abc2cb59dbc','[0.01684803,0.004069015,-0.015254444,-0.056105237,-0.015836865,0.008045041,-0.022664813,0.005294657,-0.01415778,-0.019018715,-0.00046006215,0.002132698,0.0056667626,-0.018494146,0.12046281,0.013168363,0.003899472,-0.005214462,-0.0037340547,0.02043856,-0.0034992967,0.028927699,0.0031403971,-0.0010029976,0.046311002,0.0173035,-0.0018677817,0.025642851,0.03642073,0.014183842,-0.012143363,-0.00035238813,-0.031475242,-0.0051823873,0.01635148,-0.0044438615,0.0028983005,0.011168804,-0.015455039,0.021514837,-0.014315101,0.00676742,-0.019535521,-0.002283824,-0.011259885,-0.006433502,-0.013666382,-0.028532779,0.016711848,0.027416715,0.023349663,0.01138422,-0.0064371815,-0.18518904,0.010885203,-0.017504381,-0.012094356,-0.0075510438,0.00028660693,-0.03236067,-0.014276784,0.027189234,-0.0092395665,0.007975032,-0.0019466708,0.026180992,0.039535485,0.036951542,-0.005196797,-0.041969985,0.02888966,0.007781882,0.0007458842,-0.015395983,-0.0010842894,-0.018395348,0.008893707,0.024123412,-0.0055522267,-0.0061423564,-0.0105775725,-0.026857423,-0.008148501,-0.036277823,0.02038285,-0.016753433,0.014997246,0.014592841,-0.01788589,-0.0003592354,0.028945044,-0.018398533,0.0064168586,0.008474888,-0.022199394,0.005010914,0.0070461608,0.00901423,-0.015415234,-0.02546267,-0.01829719,-0.009091631,0.00006444442,-0.0031942304,0.003281437,-0.019019516,0.012043518,0.013451489,-0.005726036,-0.0208753,0.0057285074,-0.022877015,0.021491043,0.00064694637,-0.00017045414,-0.15127869,0.0060974327,0.0047431304,-0.01732661,-0.0108266,-0.021759348,-0.01039624,0.0056073423,0.005397633,-0.009412336,-0.051974587,0.01272238,0.015446474,-0.038532108,-0.0009810354,0.010127078,-0.006845921,0.0035285582,-0.007350286,-0.0046437667,0.0055597792,0.00435626,-0.041515104,-0.019447815,-0.01365