giờ đã thu theo quy tắc hiện hành. Gia hạn theo ngày dùng giá áp dụng cho ngày mới và phụ thuộc phòng còn trống. Số tiền cuối cùng phải lấy từ đơn và công cụ của hệ thống, không tự tính rồi cam kết trong chat.','ca1c39d4424b0e75285e76da7d9133ad8078b7993f0fe969b2243985ab2b3867','[0.00009158612,0.0071992953,-0.017273266,-0.032331925,0.0014030283,0.01973808,-0.01857886,-0.01028892,-0.011518166,-0.013734384,0.008761615,0.0111062005,-0.005960275,-0.02786604,0.113363534,0.019066704,-0.0039106593,0.019360784,-0.011566773,-0.0004416618,-0.017133372,0.009852717,0.006726214,-0.010634467,-0.009527605,0.004186513,0.025654336,0.014078465,0.0345755,-0.0059798425,-0.012676653,-0.008552402,0.0132691,0.0049820174,-0.0050122035,-0.0039456435,0.017846225,-0.0026054555,-0.005203846,0.016619103,-0.008373118,0.01407672,-0.0072858064,-0.0071396097,-0.00040304704,-0.025747163,-0.011510219,-0.035252824,0.013462661,0.022858594,0.03824659,-0.011431428,0.004596574,-0.18883851,0.003897528,-0.03213928,-0.0028308602,-0.0038336804,0.012317168,-0.020960268,-0.027495049,0.007631392,-0.008580157,-0.0027941142,-0.01850282,0.008156637,0.016973836,0.023745144,0.021972166,-0.0020790666,0.029511468,-0.0057303193,0.0020529795,-0.0249248,0.009712759,-0.025714047,0.0042099403,0.023163818,-0.016923841,-0.006335529,0.020733569,-0.036556147,0.014229512,-0.017672792,0.020582411,-0.026424235,-0.003656103,0.025103066,-0.0039377646,0.016967457,0.0038605402,0.024299905,0.022474045,-0.0018423158,-0.009561577,0.0058243223,0.0038279053,0.02436966,-0.03764565,-0.030635701,-0.019550709,0.009587812,-0.010228403,0.00926484,0.03883775,-0.026429208,0.013947825,0.006655185,-0.004761696,0.005007127,0.009333583,-0.018558428,-0.0045428444,-0.0017775164,-0.012797812,-0.14155717,0.017639639,-0.008722541,-0.014673294,-0.0015738141,0.0059473403,-0.008842862,0.020834131,0.032441452,-0.021471968,-0.016479403,0.0071342858,0.012448437,-0.009821559,-0.0039687697,0.0010196547,-0.005281559,0.01664659,-0.0028772876,0.021163035,0.02421282,0.