c cấp quyền. Không đưa ra doanh thu nội bộ, thông tin nhân viên, hồ sơ khách khác, dữ liệu FaceID, mật khẩu, OTP hoặc khóa API. Với thông tin chưa được hệ thống xác nhận, nói ngắn gọn rằng cần kiểm tra với lễ tân thay vì đoán.','7c210cd53760713a67fd7457c58ff062f8f7690c8b4688e6d32541539ccf72a1','[-0.0022643835,0.010996775,-0.03711434,-0.055695478,0.0016365504,-0.0023306846,-0.023350725,0.01633635,-0.016910845,-0.022878427,-0.005494519,-0.009356642,0.012784851,-0.008554352,0.10788599,0.011359682,0.017053591,0.022186782,-0.0072163,0.02707174,0.018993843,0.010163469,-0.001587609,-0.008377379,0.032662526,-0.021847166,0.009999966,0.025039151,0.026357206,0.0022492062,-0.015022647,0.009103752,0.00070940907,0.020343732,0.0060837255,0.004631128,0.005074123,-0.013684203,-0.024197374,0.017243354,-0.012792539,-0.007730081,-0.003201903,0.00005074563,-0.020703183,0.0011836685,0.0020644455,-0.019449534,0.012923065,0.017404368,0.02394505,0.009972836,-0.015552,-0.17940697,-0.0025443581,-0.011257575,0.016997581,0.015086267,-0.013912539,-0.03860919,-0.031676948,0.027845154,-0.013904158,-0.0017892318,-0.0048501994,0.0017882008,0.022808617,0.021131707,0.021743655,-0.004543583,0.012765604,0.007374305,-0.0015052033,-0.038868543,-0.017705293,-0.015179949,0.008801402,0.02050181,0.01682555,-0.007489813,0.0050710393,-0.026098501,-0.000008769098,-0.016651256,0.03266815,-0.014362105,0.025876112,-0.013335635,-0.0141141135,0.0072696498,0.011416053,0.009450215,0.024371095,0.016109388,0.008747424,0.0067137107,-0.009007721,-0.0034136325,-0.035621304,-0.006240797,-0.0103265345,-0.0036938004,-0.0026336485,-0.015420735,0.011840778,-0.02113271,0.020702798,-0.004597667,-0.011700297,-0.0026074485,0.00017794209,-0.009195826,0.00063848624,-0.008596642,-0.0076372228,-0.15362269,0.0074375262,-0.026652452,-0.0046301363,0.0077612484,-0.0060624266,0.0016311196,-0.0075963256,0.023169262,-0.013646154,-0.031267352,0.021032436,0.004446216,-0.019085802,0.0018215757,-0.018532347,0.008923854,0.022716628,-0.011062918,-0.